def merge_and_remove_duplicates(list1: list, list2: list) -> set:
    # Combining into a set removes duplicates automatically
    return set(list1 + list2)

def replace_vowels(s: str) -> str:
    vowels = "aeiouAEIOU"
    # Shift each vowel to the next character in the alphabet
    return ''.join(chr(ord(c) + 1) if c in vowels else c for c in s)

def process_sentence(sentence: str, task: str):
    words = sentence.split()

    if task == "count_words":
        return len(words)

    elif task == "count_palindrome_words":
        return sum(1 for w in words if w == w[::-1])

    elif task == "count_words_with_repeated_chars":
        # A repeated char means unique-char count is less than total length
        return sum(1 for w in words if len(set(w)) < len(w))

    elif task == "words_with_max_len":
        max_len = max(len(w) for w in words)
        return set(w for w in words if len(w) == max_len)
